    'app.overview.kicker': 'What CounselorBot is',
    'app.overview.title': 'Three ways to use CounselorBot',
    'app.overview.body': 'CounselorBot supports reflection on learning, guidance and study choices. First choose the tool, then choose the AI counselor you want to work with.',
    'app.overview.questionnaires.title': 'Questionnaires',
    'app.overview.questionnaires.body': 'Interpret profiles from the Strategic Competences questionnaires and identify resources, difficulties and work priorities.',
    'app.overview.savickas.title': 'Savickas interview',
    'app.overview.savickas.body': 'A five-question narrative interview that connects interests, role models, personal stories and future choices.',
    'app.overview.pqbl.title': 'pQBL from a PDF',
    'app.overview.pqbl.body': 'Upload a study PDF and practise with questions and feedback generated from its content.',
    'app.home.contains': 'What you find in CounselorBot',
    'app.home.next': 'How to continue',
    'app.intro.subtitle': 'Get to know how you learn and how you find direction, in dialogue with an AI counselor.',
    'app.intro.contact': 'For questions about the platform, or to help build it, write to:',
    'app.intro.modes': 'Interpret the questionnaires, take the Savickas interview or practise on a PDF.',
    'app.home.cta': 'Start',
    'app.intro.what.title': 'What it is',
    'app.intro.what.body': 'CounselorBot is an educational counselling environment developed by Roma Tre University. It helps you make sense of your results on the strategic-competence questionnaires — how you study, how you organise yourself, how you look at the future — through a dialogue with an AI-based counselor.',
    'app.intro.how.title': 'How it works',
    'app.intro.how.s1.title': 'Choose the instrument',
    'app.intro.how.s1.body': 'A questionnaire (QSA, ZTPI, …), the Savickas interview or a study PDF.',
    'app.intro.how.s2.title': 'Choose the counselor',
    'app.intro.how.s2.body': 'Each AI counselor has a different approach.',
    'app.intro.how.s3.title': 'Enter your results',
    'app.intro.how.s3.body': 'By hand, or by uploading the questionnaire PDF.',
    'app.intro.how.s4.title': 'Talk about your profile',
    'app.intro.how.s4.body': 'A guided conversation, factor by factor, to understand strengths and areas to work on.',
    'app.intro.langs.pre': 'The strategic-competence questionnaires can be taken here in English, Spanish, French, German and Swedish. To take them in Italian, use ',
    'app.intro.langs.post': '.',
    'app.tools.title': 'Tools at your disposal',
    'app.tools.notebook.title': 'The notebook',
    'app.tools.notebook.body': 'A personal space where you note who you are, your strengths and weaknesses and what matters to you. The AI counselor uses it as context to read your results closer to your real situation.',
    'app.tools.notebook.access': 'You fill it in before your first tool; at the end of each path you are invited to update it. It stays reachable anytime from the profile icon in the top bar.',
    'app.tools.assistant.title': 'The assistant',
    'app.tools.assistant.body': 'An assistant you can ask open questions about strategic competences, the questionnaires and the platform: it answers citing the documents it draws the information from.',
    'app.tools.assistant.access': 'Open it anytime from the robot icon in the top bar.',
    'app.tools.readings.title': 'Readings and films',
    'app.tools.readings.body': 'A catalogue of books, films, articles and videos chosen and approved by the researchers. The counselor offers at most two at a time and says in one line what each helps you understand.',
    'app.tools.readings.access': 'Ask for them in the chat whenever you want (“what could I read about...”), or the counselor brings them up when the conversation makes them useful.',
    'app.tools.diagrams.title': 'Diagrams',
    'app.tools.diagrams.body': 'When an explanation holds a process, a loop or concepts tied to one another, the counselor draws it: a scheme that goes alongside the words rather than replacing them.',
    'app.tools.diagrams.access': 'They appear inside the chat. You can also ask for one: “draw me a scheme”.',
    'app.intro.expect.title': 'What to expect',
    'app.intro.expect.body': 'The counselor is an artificial intelligence: it asks you questions and suggests readings of your profile and practical strategies, but it gives no diagnoses or judgements. The right answers about your experience are yours — the dialogue is there to bring them out. A session usually takes 20–40 minutes, and you can pause and resume whenever you like.',
    'step.questionnaireSelect.desc': 'Choose which questionnaire to analyse',
