    'app.overview.savickas.body': 'Una entrevista narrativa de cinco preguntas para conectar intereses, modelos, historias personales y elecciones futuras.',
    'app.overview.pqbl.title': 'pQBL desde PDF',
    'app.overview.pqbl.body': 'Subes un PDF de estudio y practicas con preguntas y feedback generados a partir del contenido.',
    'app.home.contains': 'Qué encontrarás en CounselorBot',
    'app.home.next': 'Cómo continuar',
    'app.intro.subtitle': 'Descubre cómo estudias y cómo te orientas, en diálogo con un counselor de IA.',
    'app.intro.contact': 'Para dudas sobre la plataforma, o para colaborar en su construcción, escribe a:',
    'app.intro.modes': 'Interpreta los cuestionarios, haz la entrevista Savickas o practica con un PDF.',
    'app.home.cta': 'Empezar',
    'app.intro.what.title': 'Qué es',
    'app.intro.what.body': 'CounselorBot es un entorno de counseling formativo desarrollado por la Universidad Roma Tre. Te ayuda a interpretar los resultados de los cuestionarios de competencias estratégicas — cómo estudias, cómo te organizas, cómo miras al futuro — a través de un diálogo con un counselor basado en inteligencia artificial.',
    'app.intro.how.title': 'Cómo funciona',
    'app.intro.how.s1.title': 'Elige el instrumento',
    'app.intro.how.s1.body': 'Un cuestionario (QSA, ZTPI, …), la entrevista Savickas o un PDF de estudio.',
    'app.intro.how.s2.title': 'Elige el counselor',
    'app.intro.how.s2.body': 'Cada counselor de IA tiene un enfoque distinto.',
    'app.intro.how.s3.title': 'Introduce tus resultados',
    'app.intro.how.s3.body': 'A mano o subiendo el PDF del cuestionario.',
    'app.intro.how.s4.title': 'Dialoga sobre tu perfil',
    'app.intro.how.s4.body': 'Una conversación guiada, factor por factor, para entender puntos fuertes y áreas de mejora.',
    'app.intro.langs.pre': 'Los cuestionarios de competencias estratégicas se pueden completar aquí en inglés, español, francés, alemán y sueco. Para completarlos en italiano, usa ',
    'app.intro.langs.post': '.',
    'app.tools.title': 'Herramientas a tu disposición',
    'app.tools.notebook.title': 'El cuaderno',
    'app.tools.notebook.body': 'Un espacio personal donde anotas quién eres, tus puntos fuertes y débiles y lo que te importa. El counselor de IA lo usa como contexto para leer tus resultados más cerca de tu situación real.',
    'app.tools.notebook.access': 'Lo rellenas antes de usar tu primera herramienta; al final de cada recorrido se te propone actualizarlo. Sigue siendo accesible desde el icono de perfil de la barra superior.',
    'app.tools.assistant.title': 'El asistente',
    'app.tools.assistant.body': 'Un asistente al que puedes hacer preguntas libres sobre las competencias estratégicas, los cuestionarios y la plataforma: responde citando los documentos de los que toma la información.',
    'app.tools.assistant.access': 'Ábrelo en cualquier momento desde el icono con forma de robot en la barra superior.',
    'app.tools.readings.title': 'Lecturas y películas',
    'app.tools.readings.body': 'Un catálogo de libros, películas, artículos y vídeos elegidos y aprobados por los investigadores. El counselor te propone como máximo dos cada vez y explica en una línea qué te ayuda a entender cada uno.',
    'app.tools.readings.access': 'Los pides en el chat cuando quieras («¿qué puedo leer sobre...?»), o los trae el counselor cuando la conversación los hace útiles.',
    'app.tools.diagrams.title': 'Diagramas',
    'app.tools.diagrams.body': 'Cuando la explicación contiene un proceso, un ciclo o conceptos ligados entre sí, el counselor lo dibuja: un esquema que acompaña a las palabras, sin sustituirlas.',
    'app.tools.diagrams.access': 'Aparecen dentro del chat. También puedes pedirlos tú: «hazme un esquema».',
    'app.intro.expect.title': 'Qué esperar',
    'app.intro.expect.body': 'El counselor es una inteligencia artificial: te hace preguntas, propone lecturas de tu perfil y estrategias prácticas, pero no da diagnósticos ni valoraciones. Las respuestas correctas sobre tus experiencias las tienes tú — el diálogo sirve para hacerlas emerger. Una sesión suele durar 20–40 minutos y puedes interrumpirla y retomarla cuando quieras.',
    'step.questionnaireSelect.desc': 'Elige qué cuestionario analizar',
    'step.methodSelect.titleSuffix': 'Introducción de Datos',
    'step.methodSelect.desc': '¿Cómo quieres introducir las puntuaciones?',
