    'assistant.deniedBody': "Cet espace est réservé aux enseignants, chercheurs et administrateurs.",
    'assistant.welcome.studente': "Bonjour ! Je suis l'assistant du site competenzestrategiche.it. Je peux t'expliquer ce que sont les questionnaires, à quoi ils servent et comment ils se déroulent. Que veux-tu savoir ?",
    'assistant.welcome.docente': "Bienvenue. Je suis l'assistant d'information de competenzestrategiche.it pour les enseignants et les formateurs. Je peux fournir des informations sur les outils, la méthodologie et l'usage pédagogique, à partir des matériaux du projet.",
    'assistant.welcome.csstudente': "Bonjour ! Je suis l'assistant du projet competenzestrategiche.it. Je peux t'expliquer ce que sont les questionnaires (QSA, QSAr, ZTPI), à quoi ils servent et comment lire tes résultats. Que veux-tu savoir ?",
    'assistant.welcome.csdocente': "Bienvenue. Je suis l'assistant de competenzestrategiche.it pour les enseignants et formateurs : outils, méthodologie, validation et usage pédagogique, à partir des matériaux du projet.",
    'assistant.welcome.cbstudente': "Bonjour ! Je suis l'assistant de la plateforme CounselorBot. Je peux t'expliquer ce qu'est la plateforme, quels outils elle héberge et comment utiliser le chat, le profil et le livret dans ton parcours.",
    'assistant.welcome.cbdocente': "Bienvenue. Je suis l'assistant de la plateforme CounselorBot pour les enseignants et formateurs : la plateforme, les outils avec les counselors IA et la console de recherche/administration.",
    'assistant.welcome.dynamic': "J'utilise la base de connaissances \"{collection}\". Pose une question sur les documents indexés dans cette collection.",
    'assistant.topic.cs_strumenti.title': "Instruments",
    'assistant.topic.cs_strumenti.body': "QSA, QSAr, ZTPI : objectif, destinataires, fonctionnement et ce qu'ils mesurent.",
    'assistant.topic.cs_strumenti.prompt': "Explique-moi quels questionnaires existent et quand les utiliser. ||| Quelle est la différence entre QSA, QSAr et ZTPI, et à qui s'adressent-ils ? ||| Que mesure le QSA et pourquoi est-il utile pour comprendre comment j'étudie ?",
    'assistant.topic.cs_risultati.title': "Mes résultats",
    'assistant.topic.cs_risultati.body': "Comment lire son propre profil après un questionnaire : facteurs, stanines et livret de réflexion personnelle.",
    'assistant.topic.cs_risultati.prompt': "Que signifie mon profil QSA et comment le lire ? ||| À quoi servent les stanines dans mon résultat et comment les interpréter sans jugements ? ||| Comment utiliser le livret pour réfléchir sur mes points forts et ce qu'il faut améliorer ?",
    'assistant.topic.cs_approfondire.title': "Approfondir",
    'assistant.topic.cs_approfondire.body': "Sources, guides et études du projet competenzestrategiche.it pour approfondir les compétences stratégiques.",
    'assistant.topic.cs_approfondire.prompt': "Quelles sources du projet puis-je consulter pour approfondir les compétences stratégiques et le QSA ? ||| Où trouver les guides et les études du projet competenzestrategiche.it ? ||| Quels matériaux me conseilles-tu pour débuter avec les outils ?",
    'assistant.topic.cs_metodologia.title': "Instruments et méthodologie",
    'assistant.topic.cs_metodologia.body': "QSA, QSAr, ZTPI : items, facteurs, construits, objectif et méthodologie d'administration.",
    'assistant.topic.cs_metodologia.prompt': "Décris la structure du QSA : items, facteurs et construits. ||| Quelle est la différence entre QSA et QSAr, et quand préférer l'un ou l'autre ? ||| Comment administre-t-on les instruments dans un parcours de counseling ?",
    'assistant.topic.cs_validazione.title': "Validation",
    'assistant.topic.cs_validazione.body': "Documents sur l'adaptation linguistique, la collecte de données, les normes, les stanines et la séparation entre recherche et counseling.",
    'assistant.topic.cs_validazione.prompt': "Résume l'état de validation des outils et ce que signifie un profil expérimental. ||| Que sont les stanines et les normes, et pourquoi comptent-elles dans la lecture des profils ? ||| Comment séparer recherche et counseling dans la collecte des données ?",
    'assistant.topic.cs_didattica.title': "Usage pédagogique",
    'assistant.topic.cs_didattica.body': "Indications pour les enseignants et formateurs : comment présenter les outils, lire les profils et intégrer la réflexion en classe.",
    'assistant.topic.cs_didattica.prompt': "Comment un enseignant peut-il utiliser les questionnaires dans un parcours pédagogique ? ||| Comment présenter les résultats d'un questionnaire à une classe sans créer d'étiquettes ? ||| Quelles activités de réflexion puis-je construire à partir d'un profil QSA ?",
    'assistant.topic.cs_materiali.title': "Matériaux et études",
    'assistant.topic.cs_materiali.body': "Guides, études, colloques et documents opérationnels du projet competenzestrategiche.it.",
    'assistant.topic.cs_materiali.prompt': "Quels guides opérationnels du projet puis-je utiliser avec les instruments ? ||| Où trouver les études et colloques du projet competenzestrategiche.it ? ||| Quels matériaux me conseilles-tu pour débuter avec les outils ?",
    'assistant.topic.cb_piattaforma.title': "La plateforme",
    'assistant.topic.cb_piattaforma.body': "Ce qu'est CounselorBot, comment il fonctionne et le lien avec competenzestrategiche.it pour les questionnaires en italien.",
    'assistant.topic.cb_piattaforma.prompt': "Qu'est-ce que CounselorBot et comment fonctionne-t-il ? ||| Pour les questionnaires en italien je dois utiliser competenzestrategiche.it : pourquoi ? ||| Dans quelles langues puis-je utiliser les questionnaires sur CounselorBot ?",
    'assistant.topic.cb_strumenti.title': "Instruments hébergés",
    'assistant.topic.cb_strumenti.body': "QSA, QSAr, ZTPI, QPCS, QPCC, QAP et Savickas : objectif, destinataires et langues disponibles (test en/es/sv).",
    'assistant.topic.cb_strumenti.prompt': "Quels instruments CounselorBot héberge-t-il et à quoi servent-ils ? ||| Quelle est la différence entre les questionnaires et l'entretien de Savickas ? ||| Dans quelles langues les questionnaires sont-ils disponibles ?",
    'assistant.topic.cb_percorso.title': "Mon parcours",
    'assistant.topic.cb_percorso.body': "Chat guidé, profil, livret de réflexion, carnet et portfolio : comment les utiliser dans ton parcours.",
    'assistant.topic.cb_percorso.prompt': "Comment fonctionne le chat guidé avec le counselor IA ? ||| Comment lire mon profil et utiliser le livret de réflexion ? ||| À quoi servent le carnet et le portfolio ?",
    'assistant.topic.cb_console.title': "La plateforme",
    'assistant.topic.cb_console.body': "Ce qu'est CounselorBot, console de recherche et d'administration, lien avec competenzestrategiche.it.",
    'assistant.topic.cb_console.prompt': "Qu'est-ce que CounselorBot et que permet-il à un enseignant/chercheur ? ||| Comment mes étudiants accéderont-ils aux questionnaires ? ||| Comment gère-t-on les classes et les parcours sur la plateforme ?",
    'assistant.topic.cb_counselor.title': "Instruments et counselor",
    'assistant.topic.cb_counselor.body': "Instruments hébergés (QSA…Savickas) et personas/styles de counselor IA disponibles.",
    'assistant.topic.cb_counselor.prompt': "Quels instruments puis-je assigner aux étudiants et avec quel counselor ? ||| Quels personas/styles de counselor IA sont disponibles et comment les choisir ? ||| Quelle est la différence entre les questionnaires et l'entretien de Savickas ?",
    'assistant.topic.cb_guida.title': "Guide enseignant",
    'assistant.topic.cb_guida.body': "Comment utiliser CounselorBot avec les étudiants : réglages, classes, gestion des parcours et présentation des résultats.",
    'assistant.topic.cb_guida.prompt': "Comment configurer un parcours pour ma classe sur CounselorBot ? ||| Comment présenter les résultats aux étudiants sans créer d'étiquettes ? ||| Comment suivre les étudiants depuis la console de recherche/administration ?",

