    'app.overview.kicker': 'Ce qu’est CounselorBot',
    'app.overview.title': 'Trois façons d’utiliser CounselorBot',
    'app.overview.body': "CounselorBot accompagne la réflexion sur l'étude, l'orientation et l'apprentissage. Choisissez d'abord l'outil, puis le counselor IA avec lequel travailler.",
    'app.overview.questionnaires.title': 'Questionnaires',
    'app.overview.questionnaires.body': 'Il interprète les profils des questionnaires Competenze Strategiche et aide à reconnaître ressources, difficultés et priorités de travail.',
    'app.overview.savickas.title': 'Entretien Savickas',
    'app.overview.savickas.body': 'Un entretien narratif en cinq questions pour relier intérêts, modèles, histoires personnelles et choix futurs.',
    'app.overview.pqbl.title': 'pQBL depuis un PDF',
