    'app.home.contains': 'Ce que vous trouverez dans CounselorBot',
    'app.home.next': 'Comment continuer',
    'app.intro.subtitle': "Découvrez comment vous apprenez et comment vous vous orientez, en dialogue avec un counselor IA.",
    'app.intro.contact': "Pour toute question sur la plateforme, ou pour participer à sa construction, écrivez à :",
    'app.intro.modes': "Interprétez les questionnaires, faites l'entretien Savickas ou entraînez-vous sur un PDF.",
    'app.home.cta': 'Commencer',
    'app.intro.what.title': "Qu'est-ce que c'est",
    'app.intro.what.body': "CounselorBot est un environnement de counseling éducatif développé par l'Université Roma Tre. Il vous aide à interpréter les résultats des questionnaires de compétences stratégiques — comment vous étudiez, comment vous vous organisez, comment vous envisagez l'avenir — à travers un dialogue avec un counselor basé sur l'intelligence artificielle.",
    'app.intro.how.title': 'Comment ça marche',
    'app.intro.how.s1.title': "Choisissez l'instrument",
    'app.intro.how.s1.body': "Un questionnaire (QSA, ZTPI, …), l'entretien Savickas ou un PDF d'étude.",
    'app.intro.how.s2.title': 'Choisissez le counselor',
    'app.intro.how.s2.body': 'Chaque counselor IA a une approche différente.',
    'app.intro.how.s3.title': 'Saisissez vos résultats',
    'app.intro.how.s3.body': 'À la main ou en téléversant le PDF du questionnaire.',
    'app.intro.how.s4.title': 'Dialoguez sur votre profil',
    'app.intro.how.s4.body': 'Une conversation guidée, facteur par facteur, pour comprendre vos points forts et les axes de travail.',
    'app.intro.langs.pre': 'Les questionnaires de compétences stratégiques peuvent être remplis ici en anglais, espagnol, français, allemand et suédois. Pour les remplir en italien, utilisez ',
    'app.intro.langs.post': '.',
    'app.tools.title': 'Les outils à votre disposition',
    'app.tools.notebook.title': 'Le carnet',
    'app.tools.notebook.body': 'Un espace personnel où vous notez qui vous êtes, vos points forts et vos points faibles et ce qui compte pour vous. Le counselor IA l’utilise comme contexte pour lire vos résultats au plus près de votre situation réelle.',
    'app.tools.notebook.access': 'Vous le remplissez avant votre premier outil ; à la fin de chaque parcours, il vous est proposé de le mettre à jour. Il reste accessible via l’icône de profil en haut.',
    'app.tools.assistant.title': 'L’assistant',
    'app.tools.assistant.body': 'Un assistant à qui poser des questions libres sur les compétences stratégiques, les questionnaires et la plateforme : il répond en citant les documents dont il tire les informations.',
    'app.tools.assistant.access': 'Ouvrez-le à tout moment via l’icône en forme de robot dans la barre du haut.',
    'app.tools.readings.title': 'Lectures et films',
    'app.tools.readings.body': 'Un catalogue de livres, de films, d’articles et de vidéos choisis et validés par les chercheurs. Le counselor vous en propose deux au maximum à la fois et explique en une ligne ce que chacun aide à comprendre.',
    'app.tools.readings.access': 'Vous les demandez dans le chat quand vous voulez (« que puis-je lire sur... »), ou le counselor les apporte lorsque la conversation les rend utiles.',
    'app.tools.diagrams.title': 'Diagrammes',
    'app.tools.diagrams.body': 'Quand l’explication contient un processus, une boucle ou des concepts liés entre eux, le counselor le dessine : un schéma qui accompagne les mots, sans les remplacer.',
    'app.tools.diagrams.access': 'Ils apparaissent dans le chat. Vous pouvez aussi en demander un : « fais-moi un schéma ».',
    'app.intro.expect.title': "À quoi s'attendre",
    'app.intro.expect.body': "Le counselor est une intelligence artificielle : il vous pose des questions, propose des lectures de votre profil et des stratégies pratiques, mais ne donne ni diagnostics ni évaluations. Les bonnes réponses sur vos expériences, c'est vous qui les avez — le dialogue sert à les faire émerger. Une séance dure en général 20–40 minutes et vous pouvez l'interrompre et la reprendre quand vous voulez.",
    'step.questionnaireSelect.desc': 'Choisissez le questionnaire à analyser',
