    'guide.section1.title': 'Connexion',
    'guide.section1.body': 'Le premier \u00e9cran vous demande de vous connecter avec votre compte pour utiliser CounselorBot, choisir un conseiller et sauvegarder votre parcours. Cliquez sur \u00ab Se connecter \u00e0 CounselorBot \u00bb et continuez avec votre compte ai4educ.',
    'guide.section2.title': 'La premi\u00e8re fois',
    'guide.section2.body': '\u00c0 votre premi\u00e8re visite, vous voyez une page d\u2019accueil : ce qu\u2019est CounselorBot, ce que vous y trouvez (questionnaires, entretien Savickas, pQBL depuis un PDF) et son fonctionnement en quatre \u00e9tapes. Appuyez sur \u00ab Commencer \u00bb.',
    'guide.section3.title': 'Votre accueil',
    'guide.section3.body': 'La page d\u2019accueil vous permet de reprendre o\u00f9 vous en \u00e9tiez ou de choisir un instrument. En haut figurent votre conseiller et vos pr\u00e9f\u00e9rences. En dessous, les instruments sont group\u00e9s en cat\u00e9gories, chacun avec \u00ab Remplir le questionnaire \u00bb, \u00ab Analyser les r\u00e9sultats \u00bb et \u00ab D\u00e9tails \u00bb.',
    'guide.section4.title': 'Choisir votre conseiller',
    'guide.section4.body': 'Chaque conseiller IA a une approche diff\u00e9rente. Le s\u00e9lecteur les regroupe en conseillers locaux et cloud : cliquez-en un pour le s\u00e9lectionner, puis utilisez l\u2019unique fl\u00e8che de retour.',
    'guide.section5.title': 'Choisir un outil',
    'guide.section5.body': 'Le s\u00e9lecteur montre tout ce qui est disponible : mettre une id\u00e9e au point, les questionnaires des Comp\u00e9tences Strat\u00e9giques, l\u2019entra\u00eenement depuis un PDF et ce qui arrive. Choisissez une carte et appuyez sur \u00ab Continuer \u00bb.',
    'guide.section6.title': 'Le Carnet',
    'guide.section6.body': 'Le carnet est votre profil personnel : \u00e2ge, contexte, objectifs, difficult\u00e9s. Le conseiller IA l\u2019utilise pour lire vos r\u00e9sultats au plus pr\u00e8s de votre situation r\u00e9elle. Vous le remplissez avant votre premier outil et le mettez \u00e0 jour \u00e0 la fin de chaque parcours.',
    'guide.section7.title': 'La discussion guid\u00e9e',
    'guide.section7.body': 'L\u2019exp\u00e9rience centrale : une conversation avec le conseiller IA sur votre profil, facteur par facteur. Vous pouvez ouvrir vos scores \u00e0 tout moment et suivre la progression du parcours.',
    'guide.chat.overviewAlt': 'Démonstration de la discussion guidée avec parcours, scores et conversation.',
    'guide.chat.overviewCaption': 'Vue complète de la discussion guidée. Les données et les messages sont des exemples.',
    'guide.chat.controlsTitle': 'Commandes de la conversation',
    'guide.chat.controlsIntro': 'Les commandes principales restent près du champ de saisie. Les icônes affichent leur nom au survol ou lorsqu\u2019elles reçoivent le focus au clavier.',
    'guide.chat.controlsAlt': 'Détail des commandes : questions suggérées, gel de session, longueur, message et envoi.',
    'guide.chat.controlsCaption': 'Détail de la barre d\u2019interaction ; la longueur Moyenne est sélectionnée dans l\u2019exemple.',
    'guide.chat.suggested.title': 'Questions suggérées',
    'guide.chat.suggested.body': 'Sélectionnez une proposition pour la copier dans le champ. Vous pouvez la modifier avant de l\u2019envoyer.',
    'guide.chat.freeze.title': 'Geler la séance',
    'guide.chat.freeze.body': 'La session s\u2019enregistre seule après chaque réponse : si vous partez, fermez l\u2019onglet ou revenez en arrière, vous la retrouvez dans « Reprendre » dans l\u2019en-tête, même sur un autre appareil. Le flocon fait la même chose et ferme la discussion immédiatement.',
    'guide.chat.length.title': 'Longueur de la réponse',
    'guide.chat.length.body': 'Les trois boutons choisissent Courte (80 mots maximum), Moyenne (180, par défaut) ou Longue (350). Le bouton sombre est actif ; le choix vaut dès la réponse suivante.',
    'guide.chat.message.title': 'Message et envoi',
    'guide.chat.message.body': 'Écrivez dans le champ et utilisez la flèche pour envoyer. Les commandes sont désactivées pendant la génération.',
    'guide.chat.navigation.title': 'Étapes du parcours',
    'guide.chat.navigation.body': '« Étape précédente » revient à une phase visitée ; « Étape suivante » poursuit le parcours. Le panneau Parcours indique toujours la phase active.',
    'guide.chat.feedback.title': 'Écoute et avis',
    'guide.chat.feedback.body': '« Écouter » lit la réponse à voix haute. Les pouces indiquent si une réponse avec stratégie ou référence a été utile.',
    'guide.chat.keyboardHint': 'Raccourcis : Entrée envoie le message ; Maj+Entrée crée une nouvelle ligne. Survolez les icônes, ou utilisez Tab, pour lire leur nom.',
    'guide.section8.title': 'S\u2019entra\u00eener depuis un PDF (pQBL)',
    'guide.section8.body': 'T\u00e9l\u00e9versez un PDF d\u2019\u00e9tude (texte s\u00e9lectionnable, 10 Mo max), choisissez le nombre de questions et entra\u00eenez-vous avec des questions et un retour imm\u00e9diat g\u00e9n\u00e9r\u00e9s \u00e0 partir de son contenu.',
    'guide.section9.title': 'Fiche outil',
    'guide.section9.body': 'Chaque instrument poss\u00e8de une page de d\u00e9tail avec ce qu\u2019il explore, son d\u00e9roulement, les donn\u00e9es requises et, quand elle est disponible, un lien direct pour remplir le questionnaire en ligne.',
