    'counselor.deselect': 'Counselor abwählen',
    'app.overview.kicker': 'Was CounselorBot ist',
    'app.overview.title': 'Drei Arten, CounselorBot zu nutzen',
    'app.overview.body': 'CounselorBot unterstützt die Reflexion über Lernen, Orientierung und Studienentscheidungen. Wählen Sie zuerst das Instrument und dann den KI-Counselor, mit dem Sie arbeiten möchten.',
    'app.overview.questionnaires.title': 'Fragebögen',
    'app.overview.questionnaires.body': 'Er interpretiert Profile aus den Competenze-Strategiche-Fragebögen und hilft, Ressourcen, Schwierigkeiten und Arbeitsprioritäten zu erkennen.',
    'app.overview.savickas.title': 'Savickas-Interview',
    'app.overview.savickas.body': 'Ein narratives Interview mit fünf Fragen, das Interessen, Vorbilder, persönliche Geschichten und zukünftige Entscheidungen verbindet.',
    'app.overview.pqbl.title': 'pQBL aus einem PDF',
    'app.overview.pqbl.body': 'Sie laden ein Lern-PDF hoch und üben mit Fragen und Feedback, die aus dem Inhalt generiert werden.',
    'app.home.contains': 'Was Sie in CounselorBot finden',
    'app.home.next': 'So geht es weiter',
    'app.intro.subtitle': 'Erkenne, wie du lernst und dich orientierst – im Dialog mit einem KI-Counselor.',
    'app.intro.contact': 'Bei Fragen zur Plattform oder um beim Aufbau mitzuwirken, schreib an:',
    'app.intro.modes': 'Interpretiere die Fragebögen, führe das Savickas-Interview oder übe an einem PDF.',
    'app.home.cta': 'Starten',
    'app.intro.what.title': 'Was ist das',
    'app.intro.what.body': 'CounselorBot ist eine Umgebung für Bildungs-Counseling, entwickelt von der Universität Roma Tre. Es hilft dir, die Ergebnisse der Fragebögen zu strategischen Kompetenzen zu verstehen — wie du lernst, wie du dich organisierst, wie du in die Zukunft blickst — im Dialog mit einem KI-basierten Counselor.',
    'app.intro.how.title': 'Wie es funktioniert',
    'app.intro.how.s1.title': 'Wähle das Instrument',
    'app.intro.how.s1.body': 'Ein Fragebogen (QSA, ZTPI, …), das Savickas-Interview oder ein Lern-PDF.',
    'app.intro.how.s2.title': 'Wähle den Counselor',
    'app.intro.how.s2.body': 'Jeder KI-Counselor hat einen anderen Ansatz.',
    'app.intro.how.s3.title': 'Gib deine Ergebnisse ein',
    'app.intro.how.s3.body': 'Von Hand oder per Upload des Fragebogen-PDFs.',
    'app.intro.how.s4.title': 'Sprich über dein Profil',
    'app.intro.how.s4.body': 'Ein geführtes Gespräch, Faktor für Faktor, um Stärken und Arbeitsfelder zu verstehen.',
    'app.intro.langs.pre': 'Die Fragebögen zu strategischen Kompetenzen können hier auf Englisch, Spanisch, Französisch, Deutsch und Schwedisch ausgefüllt werden. Zum Ausfüllen auf Italienisch nutze ',
    'app.intro.langs.post': '.',
    'app.tools.title': 'Werkzeuge, die dir zur Verfügung stehen',
    'app.tools.notebook.title': 'Das Notizbuch',
    'app.tools.notebook.body': 'Ein persönlicher Raum, in dem du festhältst, wer du bist, deine Stärken und Schwächen und was dir wichtig ist. Der KI-Counselor nutzt es als Kontext, um deine Ergebnisse näher an deiner realen Situation zu lesen.',
    'app.tools.notebook.access': 'Du füllst es vor dem ersten Werkzeug aus; am Ende jedes Weges wirst du gebeten, es zu aktualisieren. Es bleibt jederzeit über das Profil-Symbol oben rechts erreichbar.',
    'app.tools.assistant.title': 'Der Assistent',
    'app.tools.assistant.body': 'Ein Assistent, dem du freie Fragen zu den strategischen Kompetenzen, den Fragebögen und der Plattform stellen kannst: Er antwortet und nennt die Dokumente, aus denen er die Informationen bezieht.',
    'app.tools.assistant.access': 'Öffne ihn jederzeit über das Roboter-Symbol in der oberen Leiste.',
    'app.tools.readings.title': 'Lektüre und Filme',
    'app.tools.readings.body': 'Ein Katalog von Büchern, Filmen, Artikeln und Videos, ausgewählt und freigegeben von den Forschenden. Der Counselor schlägt dir höchstens zwei auf einmal vor und sagt in einer Zeile, was jedes davon verstehen hilft.',
    'app.tools.readings.access': 'Du fragst im Chat danach, wann du willst („was kann ich über ... lesen“), oder der Counselor bringt sie ein, wenn das Gespräch sie nützlich macht.',
    'app.tools.diagrams.title': 'Diagramme',
    'app.tools.diagrams.body': 'Wenn eine Erklärung einen Prozess, einen Kreislauf oder miteinander verbundene Begriffe enthält, zeichnet der Counselor sie: ein Schema, das die Worte begleitet, statt sie zu ersetzen.',
    'app.tools.diagrams.access': 'Sie erscheinen im Chat. Du kannst auch selbst danach fragen: „zeichne mir ein Schema“.',
    'app.intro.expect.title': 'Was dich erwartet',
    'app.intro.expect.body': 'Der Counselor ist eine künstliche Intelligenz: Er stellt dir Fragen, schlägt Lesarten deines Profils und praktische Strategien vor, gibt aber keine Diagnosen oder Bewertungen ab. Die richtigen Antworten über deine Erfahrungen hast du selbst — der Dialog hilft, sie sichtbar zu machen. Eine Sitzung dauert in der Regel 20–40 Minuten; du kannst sie jederzeit unterbrechen und fortsetzen.',
    'step.questionnaireSelect.desc': 'Wählen Sie den zu analysierenden Fragebogen',
    'step.methodSelect.titleSuffix': 'Dateneingabe',
    'step.methodSelect.desc': 'Wie möchten Sie die Werte eingeben?',
    'step.manualInput.title': 'Werte Eingeben',
    'step.manualInput.desc': 'Geben Sie für jeden Faktor Werte von 1 bis 9 ein',
    'step.uploadInput.title': 'Dokument Hochladen',
    'step.uploadInput.desc': 'Die KI extrahiert die Daten automatisch',
