    'selector.explain.step2.title': 'Profil lesen',
    'selector.explain.step2.body': 'CounselorBot ordnet die Ergebnisse in verständliche Bereiche und hilft, Ressourcen, Schwierigkeiten und Prioritäten zu erkennen.',
    'selector.explain.step3.title': 'Mit Ihrem Counselor sprechen',
