    // Anleitung zur Oberflaeche
    'nav.guide': 'Anleitung',
    'guide.title': 'Anleitung zur Oberfl\u00e4che',
    'guide.subtitle': 'Eine kurze Tour durch CounselorBot, Abschnitt f\u00fcr Abschnitt.',
    'guide.back': 'Zur\u00fcck zur Startseite',
    'guide.indexTitle': 'Inhalt',
    'guide.zoomHint': 'Bild vergr\u00f6\u00dfern',
    'guide.zoomClose': 'Schlie\u00dfen',
    'guide.section1.title': 'Anmeldung',
    'guide.section1.body': 'Der erste Bildschirm bittet dich, dich mit deinem Konto anzumelden, um CounselorBot zu nutzen, einen Counselor zu w\u00e4hlen und deinen Weg zu speichern. Klicke auf \u201eBei CounselorBot anmelden\u201c und fahre mit deinem ai4educ-Konto fort.',
    'guide.section2.title': 'Das erste Mal',
    'guide.section2.body': 'Bei deinem ersten Besuch siehst du eine Willkommensseite: was CounselorBot ist, was du findest (Frageb\u00f6gen, Savickas-Interview, pQBL aus PDF) und wie es in vier Schritten funktioniert. Dr\u00fccke \u201eStarten\u201c.',
    'guide.section3.title': 'Deine Startseite',
    'guide.section3.body': 'Die Startseite l\u00e4sst dich dort weitermachen, wo du aufgeh\u00f6rt hast, oder ein Instrument w\u00e4hlen. Oben siehst du deinen Counselor und deine Vorgehensweise. Darunter sind die Instrumente in Kategorien gruppiert, jeweils mit \u201eFragebogen ausf\u00fcllen\u201c, \u201eErgebnisse analysieren\u201c und \u201eDetails\u201c.',
    'guide.section4.title': 'W\u00e4hle deinen Counselor',
    'guide.section4.body': 'Jeder KI-Counselor hat einen anderen Ansatz. Der Selektor gruppiert sie in lokale und Cloud-Counselor: Klicke einen an, um ihn auszuw\u00e4hlen, und nutze den einzigen Zur\u00fcck-Pfeil.',
    'guide.section5.title': 'W\u00e4hle ein Werkzeug',
    'guide.section5.body': 'Der Selektor zeigt alles Verf\u00fcgbare: eine Idee fokussieren, die Frageb\u00f6gen der Strategischen Kompetenzen, das Training aus PDF und was bald kommt. W\u00e4hle eine Karte und dr\u00fccke \u201eWeiter\u201c.',
    'guide.section6.title': 'Das Notizbuch',
    'guide.section6.body': 'Das Notizbuch ist dein pers\u00f6nliches Profil: Alter, Kontext, Ziele, Schwierigkeiten. Der KI-Counselor nutzt es, um deine Ergebnisse n\u00e4her an deiner realen Situation zu lesen. Du f\u00fcllst es vor deinem ersten Werkzeug aus und aktualisierst es am Ende jedes Weges.',
    'guide.section7.title': 'Der gef\u00fchrte Chat',
    'guide.section7.body': 'Das zentrale Erlebnis: ein Gespr\u00e4ch mit dem KI-Counselor \u00fcber dein Profil, Faktor f\u00fcr Faktor. Du kannst jederzeit deine Werte \u00f6ffnen und den Fortschritt des Weges verfolgen.',
    'guide.chat.overviewAlt': 'Beispiel des geführten Chats mit Ablauf, Werten und Unterhaltung.',
    'guide.chat.overviewCaption': 'Vollständige Ansicht des geführten Chats. Daten und Nachrichten sind Beispiele.',
    'guide.chat.controlsTitle': 'Steuerung der Unterhaltung',
    'guide.chat.controlsIntro': 'Die wichtigsten Bedienelemente bleiben beim Eingabefeld. Symbole zeigen ihren Namen beim Darüberfahren oder beim Tastaturfokus.',
    'guide.chat.controlsAlt': 'Detail der Chatsteuerung: Vorschläge, Sitzung einfrieren, Antwortlänge, Nachricht und Senden.',
    'guide.chat.controlsCaption': 'Detail der Interaktionsleiste; im Beispiel ist Mittel ausgewählt.',
    'guide.chat.suggested.title': 'Vorgeschlagene Fragen',
    'guide.chat.suggested.body': 'Wähle einen Vorschlag, um ihn ins Textfeld zu übernehmen. Du kannst ihn vor dem Senden bearbeiten.',
    'guide.chat.freeze.title': 'Sitzung einfrieren',
    'guide.chat.freeze.body': 'Die Sitzung speichert sich nach jeder Antwort von selbst: Wenn du weggehst, den Tab schließt oder zurückgehst, findest du sie in der Kopfzeile unter „Fortsetzen“ wieder, auch auf einem anderen Gerät. Die Schneeflocke tut dasselbe und schließt den Chat sofort.',
    'guide.chat.length.title': 'Antwortlänge',
    'guide.chat.length.body': 'Die drei Tasten wählen Kurz (bis 80 Wörter), Mittel (180, Standard) oder Lang (350). Die dunkle Taste ist aktiv; die Wahl gilt ab der nächsten Antwort.',
    'guide.chat.message.title': 'Nachricht und Senden',
    'guide.chat.message.body': 'Schreibe ins Feld und sende mit dem Pfeil. Während eine Antwort erzeugt wird, sind die Bedienelemente deaktiviert.',
    'guide.chat.navigation.title': 'Schritte des Ablaufs',
    'guide.chat.navigation.body': '„Vorheriger Schritt“ kehrt zu einer besuchten Phase zurück; „Nächster Schritt“ setzt den Ablauf fort. Das Ablaufpanel markiert die aktive Phase.',
    'guide.chat.feedback.title': 'Anhören und Feedback',
    'guide.chat.feedback.body': '„Anhören“ liest die Antwort vor. Daumen hoch oder runter erfasst, ob eine Antwort mit Strategie oder Referenz hilfreich war.',
    'guide.chat.keyboardHint': 'Tastatur: Eingabe sendet; Umschalt+Eingabe fügt eine neue Zeile ein. Fahre über Symbole oder nutze Tab, um ihre Namen zu lesen.',
    'guide.section8.title': 'Trainiere mit einem PDF (pQBL)',
    'guide.section8.body': 'Lade ein Lern-PDF hoch (ausw\u00e4hlbarer Text, max. 10 MB), w\u00e4hle die Anzahl der Fragen und \u00fcbe mit Fragen und sofortigem Feedback aus dessen Inhalt.',
    'guide.section9.title': 'Werkzeug\u00fcbersicht',
